import{_ as l,c as t,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"易附录纂注卷十三","description":"易附录纂注 - 易附录纂注卷十三","frontmatter":{"title":"易附录纂注卷十三","description":"易附录纂注 - 易附录纂注卷十三"},"headers":[],"relativePath":"zh/classics/yifulu-zuanzhu/014.md","filePath":"zh/classics/yifulu-zuanzhu/014.md"}'),r={name:"zh/classics/yifulu-zuanzhu/014.md"};function u(i,a,c,o,p,d){return s(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"易附录纂注卷十三",tabindex:"-1"},[n("易附录纂注卷十三 "),e("a",{class:"header-anchor",href:"#易附录纂注卷十三","aria-label":"Permalink to “易附录纂注卷十三”"},"​")],-1),e("p",null,"钦定四库全书",-1),e("p",null,"元胡一桂撰",-1),e("p",null,"愚按：五赞大要皆教人以象占之学。首篇原奇偶之象，推象之由也。次篇述作者之旨，为占而作也。三篇明筮以发其占。四篇稽类以考其象。五篇以警学名。欲人读易之际，常如卜筮之临，假象辞以为仪则，而终趋于吉。是又会象占而一之也。先生尝曰：「某解易只作卜筮之书，今五赞皆以象占示教，其旨深矣。」 太一肇判，阴降阳升。阳一以施，阴两而承。惟皇昊羲，仰观俯察。奇偶既陈，两仪斯设。既干乃支，一各生两。阴阳交错，以立四象。奇加以奇，曰阳之阳。奇而加偶，阳阴以章。偶而加奇，阴内阳外。偶复加偶，阴与阴会。两一既分，一复生两。三才在目，八卦指掌。奇奇而奇，初一曰乾。奇奇而偶，兑次二焉。奇偶而奇，次三曰离。奇偶而偶，四震以随。偶奇而奇，巽居次五。偶奇而偶，坎六斯睹；偶偶而奇，艮居次七。偶偶而偶，坤八以毕。初画为仪，中画为象，上画卦成人文斯朗。因而重之。一贞八悔。六十四卦由内达外。附录。 「贞悔」出洪范。贞是正底，便是体；悔是过底，动则有悔。凡悔，都是过了方悔。这悔是过底意思，亦是多底意思。下三爻便是正卦，上三爻似是过多了。亦似今占卜分甚主客。贺孙。贞是事之始，悔是事之终；贞是事之主，悔是事之客；贞是在我底，悔是应人底。「一贞八悔」，如乾至泰，内体皆乾，是一贞；外体八卦，是八悔。余放此。义刚。 交易为体，往此来彼。附录。 先天图一边本都是阳，一边本都是阴。阳中有阴，阴中有阳，便是阳往交易阴，阴来交易阳，两边各各相对。其实非此往彼来，只其象如此。僩。 「变易为用」，时静时动。降帝而王，传夏历商。「有占无文，民用弗章。」文王系彖，周公系爻，视此八卦，二纯六交。乃乾斯父，乃坤斯母。震坎艮男，巽离兑女，离南坎北，震东兑西，乾坤艮巽，位以四维。建官立师，命曰周易。孔圣传之，是为十翼。遭秦弗烬，及宋而明，邵传羲画，程演周经。象陈数列，言尽理得，弥亿万年，永著常式。",-1),e("p",null,"昔在上古，世质民淳，是非莫别，利害不分。风气既开，乃生圣人，聪明睿知，出类超群。仰观俯察，始画奇偶，教之卜筮，以断可否。作为君饰，开凿户牖，民用不迷，以有常守。降及中古，世变风移，淳浇质丧，民伪日滋。穆穆文王，身蒙大难，安土乐天，惟世之患。乃本卦义，系此彖辞。爰及周公，六爻是资。因事设教，丁宁详密，必中必正，乃亨乃吉。语子惟孝，语臣则忠，钩深阐微，如日之中。爰暨末流，淫于术数，偻句成欺，黄裳亦误。纂注 左传昭公二十五年：臧昭伯如晋，臧会窃其宝龟偻句以卜，为信与僭，僭吉。后平子立会，会曰：「偻句不余欺也。」注：偻句，龟所出地名。僭，不信也，谓求立为臧氏后也。黄裳事见坤卦六五爻。 大哉孔子，晚好是书，韦编既绝，八索以祛。乃作彖、象，十翼之篇，专用义理，发挥经言。居省象辞，动察变占，存亡进退，陟降飞潜，曰毫曰厘，匪差匪缪，假我数年，庶无大咎。恭惟三古，四圣一心，垂象炳明，千载是临。惟是学者，不本其初，文辞象数，或肆或拘。嗟予小子，既微且陋，钻仰没身，奚测奚究。匪警滋荒，匪识滋漏，维用存疑，敢曰垂后。",-1),e("p",null,"倚数之元，参天两地，衍而极之，五十乃备。是曰大衍，虚一无为。其为用者，四十九蓍。信手平分，置右于几。取右一蓍，挂左小指。乃以右手，揲左之策。四四之余，归之于扐。初扐左手，无名指间，右策左揲，将指是安。再扐之奇，通挂之算，不五则九，是谓一变。置此挂扐，再用存策，分挂揲归，复准前式。三亦如之，奇皆四八。三变既备，数斯可察。数之可察，其辨伊何。四五为少，八九为多。三少为九，是曰老阳。三多为六，老阴是当。一少两多，少阳之七。孰八少阴，少两多一。既得初爻，复合前蓍。四十有九，如前之为。三变一爻，通十八变。六爻发挥，卦体可见。老极而变，少守其常。六爻皆守，彖辞是当。变视其爻，两兼首尾。变及三爻，占两卦体。或四或五，视彼所存。四二五一，二分一专。皆变而他，新成旧毁。消息盈虚，舍此视彼。乾占用九，坤占用六。「泰」愕匪人，姤喜来复。",-1),e("p",null,"八卦之象，说卦详焉。考之于经，其用弗专。彖以情言，象以象告。惟是之求，斯得其要。乾健天行，坤顺地从。震动为雷，巽入木风。坎险水泉，亦云亦雨。离丽文明，电日而火。艮止为山，兑说为泽。以是举之，其要斯得。凡卦六虚，奇偶殊位。奇阳偶阴，各以其类。得位为正，二五为中，二臣五君，初始上终。贞悔体分，爻以位应。阴阳相求，乃得其正。凡阳斯淑，君子居之。凡阴斯慝，小人是为。常可类求，变非例测。非常曷变？谨此为则。",-1),e("p",null,"读易之法，先正其心。肃容端席，有翼其临。于卦于爻，如筮斯得。假彼象辞，为我仪则。字从其训，句逆其情，事因其理，意适其平。曰否曰臧，如目斯见，曰止曰行，如足斯践。毋宽以略，毋密以穷，毋固而可，毋必而通。平易从容，自表而里。及其贯之，万事一理。理定既实，事来尚虚。用应始有，体该本无。稽实待虚，存体应用。执古御今，由静制动。附录：圣人作易，只说一个理，都未曾有许多事，却待甚么事来凑？所谓「事来尚虚」，盖谓事之方来，尚虚而未有。若论其理，则先自定，固已实矣。「用应始有」，谓理之用实，故有。「体该本无」，谓理之体该万物，初无形迹可见，故无。下云「稽考实理，以待事物之来」，存此理之体，以应无穷之用。「执古」，古便是易书里面言语。「御今」，今便是今日之事。「以静制动」，理便是静底，事便是动底。敬之 洁静精微，是之谓易。体之在我，动有常吉。在昔程氏，继周绍孔，奥指宏刚，星陈极拱。惟斯未启，以俟后人，小子狂简，敢述而申。易附录纂注卷十三。",-1)])])}const m=l(r,[["render",u]]);export{h as __pageData,m as default};
